import { checkPassword } from "@/modules/access/domain/password-policy";

/**
 * The first password of a stadium's owner, generated by the platform admin (DR-006). 16 characters
 * from an alphabet with no look-alikes (no I, O, l, o, 0 or 1), so it can be read aloud or typed
 * from a screen. The randomness is passed in (`randomBytes`), so this stays pure and testable.
 */
export const OWNER_PASSWORD_LENGTH = 16;
export const OWNER_PASSWORD_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789";

/** Largest multiple of the alphabet size below 256: bytes at or above it are skipped, so no character is likelier. */
const LIMIT = 256 - (256 % OWNER_PASSWORD_ALPHABET.length);

export function generateOwnerPassword(
  randomBytes: (size: number) => Uint8Array,
  context: { identifier: string; slug: string },
): string {
  for (;;) {
    let password = "";
    while (password.length < OWNER_PASSWORD_LENGTH) {
      for (const byte of randomBytes(OWNER_PASSWORD_LENGTH * 2)) {
        if (byte >= LIMIT) continue;
        password += OWNER_PASSWORD_ALPHABET[byte % OWNER_PASSWORD_ALPHABET.length];
        if (password.length === OWNER_PASSWORD_LENGTH) break;
      }
    }
    // Practically always true; checked so the shared policy is the rule, not our assumption.
    if (checkPassword(password, context) === null) return password;
  }
}
